const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("labels: valid labels accepted, invalid rejected", async () => {
  const { base, close } = startServer();
  try {
    const ok = await api(base, "POST", "/api/links", {
      url: "https://example.com",
      labels: ["news", "big-story"],
    });
    assert.strictEqual(ok.status, 201);
    assert.deepStrictEqual(ok.json.labels.slice().sort(), ["big-story", "news"]);

    const bad = await api(base, "POST", "/api/links", {
      url: "https://example.com",
      labels: ["Not Valid!"],
    });
    assert.strictEqual(bad.status, 400);
  } finally {
    await close();
  }
});

test("labels: default to empty array when omitted", async () => {
  const { base, close } = startServer();
  try {
    const resp = await api(base, "POST", "/api/links", { url: "https://example.com" });
    assert.strictEqual(resp.status, 201);
    assert.deepStrictEqual(resp.json.labels, []);
  } finally {
    await close();
  }
});

test("labels: GET /api/links?label= filters", async () => {
  const { base, close } = startServer();
  try {
    await api(base, "POST", "/api/links", { url: "https://a.example.com", slug: "link-a", labels: ["news"] });
    await api(base, "POST", "/api/links", { url: "https://b.example.com", slug: "link-b", labels: ["news", "sports"] });
    await api(base, "POST", "/api/links", { url: "https://c.example.com", slug: "link-c", labels: ["sports"] });

    const resp = await api(base, "GET", "/api/links?label=news");
    const slugs = resp.json.map((l) => l.slug).sort();
    assert.deepStrictEqual(slugs, ["link-a", "link-b"]);

    const none = await api(base, "GET", "/api/links?label=missing");
    assert.deepStrictEqual(none.json, []);
  } finally {
    await close();
  }
});

